 68	function errorMessage(error: unknown): string {
 69	  return error instanceof Error ? error.message : String(error)
 70	}
 71	
 72	function describeRetirements(retirements: readonly WorkerContainerRetirement[]): string {
 73	  const names = retirements.map(retirement => retirement.name)
 74	  return names.length === 0 ? '0' : `${names.length} (${names.join(', ')})`
 75	}
