 77	/** Sondea el binario de Podman; un rechazo o una salida distinta de 0 es «no disponible» con su causa. */
 78	export async function probePodman(podman: PodmanExecutor): Promise<PodmanAvailability> {
 79	  try {
 80	    const result = await podman.run(PODMAN_PROBE_ARGV)
 81	    if (result.exitCode === 0) return { available: true }
 82	    const detail = result.stderr.trim() || 'sin stderr'
 83	    return { available: false, cause: `podman ${PODMAN_PROBE_ARGV.join(' ')} salió ${result.exitCode}: ${detail}` }
 84	  } catch (error) {
 85	    return { available: false, cause: errorMessage(error) }
 86	  }
 87	}
