 89	class InactiveWorkerSupervision implements WorkerSupervision {
 90	  async shutdown(): Promise<void> {}
 91	}
 92	
 93	class ActiveWorkerSupervision implements WorkerSupervision {
 94	  constructor(
 95	    private readonly manager: WorkerManagerLifecycle,
 96	    private readonly log: SupervisorLogSink,
 97	  ) {}
 98	
 99	  async reconcile(): Promise<void> {
100	    try {
101	      const orphans = await this.manager.reconcileOrphans()
102	      this.log.write(PODMAN_LOG_LABEL, `huérfanos retirados al arrancar: ${describeRetirements(orphans)}`)
103	    } catch (error) {
104	      this.log.write(PODMAN_LOG_LABEL, `no se pudieron reconciliar los huérfanos al arrancar: ${errorMessage(error)}`)
105	    }
106	  }
107	
108	  async shutdown(): Promise<void> {
109	    try {
110	      const retired = await this.manager.retireAll()
111	      this.log.write(PODMAN_LOG_LABEL, `workers retirados al apagar: ${describeRetirements(retired)}`)
112	    } catch (error) {
113	      this.log.write(PODMAN_LOG_LABEL, `no se pudieron retirar los workers al apagar: ${errorMessage(error)}`)
114	    }
115	  }
116	}
117	
118	/** Arranca la supervisión: sondea Podman y, si está, reconcilia los huérfanos. Nunca lanza. */
119	export async function startWorkerSupervision(
120	  workers: DaemonPodmanWorkers,
121	  log: SupervisorLogSink,
122	): Promise<WorkerSupervision> {
123	  const availability = await probePodman(workers.podman)
124	  if (!availability.available) {
125	    log.write(PODMAN_LOG_LABEL, `sin Podman en el anfitrión (${availability.cause}); ` +
126	      'el daemon sigue sin workers especializados que gestionar')
127	    return new InactiveWorkerSupervision()
128	  }
129	  const supervision = new ActiveWorkerSupervision(workers.manager, log)
130	  await supervision.reconcile()
131	  return supervision
132	}
