138	/** El manager real del daemon: Podman del toolchain, `bin/hardware-inventory` y `gpu_monitor`. */
139	export function createDaemonPodmanWorkers(daemonPid: number): DaemonPodmanWorkers {
140	  const podman = createPodmanExecutor()
141	  const manager = new PodmanWorkerManager({
142	    lifecycle: createWorkerContainerLifecycleDeps(podman),
143	    daemonPid,
144	    hardwareVerdict: readHardwareVerdict,
145	    vram: createVramAdmissionPort(vramLedgerPath()),
146	  })
147	  return { manager, podman }
148	}

